import Foundation

enum GuideDestination: String, Sendable { case camera, looks, library, styles }
enum GuideVisual: String, Sendable { case camera, looks, brightness, warmth, crop, style, save, color, film, selective }

struct GuideTopic: Identifiable, Sendable {
    let id: String
    let section: String
    let title: String
    let symbol: String
    let visual: GuideVisual
    let destination: GuideDestination?
    let summary: String
    let steps: [String]
    let note: String
    let keywords: String
}

enum GuideCatalog {
    static let sections = ["Getting Started", "Camera", "Looks & Styles", "Editing", "Library", "Saving & Sharing"]
    static let topics: [GuideTopic] = [
        GuideTopic(id: "first-photo", section: "Getting Started", title: "Your first photo", symbol: "camera", visual: .camera, destination: .camera, summary: "Start with a free look and make one photo from start to finish.", steps: ["Open Looks and choose a free filter. You can also swipe across the camera preview to change looks.", "Tap your subject to focus. Open Camera Options → Exposure if the preview needs to be brighter or darker.", "Press the shutter, then open Library and tap your photo.", "Adjust the look strength, then Save to add the edited photo to Photos or Share to send a copy."], note: "You can skip any guide topic and return whenever you need help.", keywords: "beginner tutorial quick start"),
        GuideTopic(id: "focus", section: "Camera", title: "Focus & brightness", symbol: "viewfinder", visual: .brightness, destination: .camera, summary: "Focus chooses what is sharp. Exposure compensation makes the camera image brighter or darker.", steps: ["Tap the subject in the preview to focus and meter it.", "Use the focus-lock control to hold focus and exposure; unlock it when the subject or lighting changes.", "Open Camera Options → Exposure. Start near 0 and adjust gently; reset to 0 when finished."], note: "A very bright exposure can lose detail in the sky.", keywords: "dark bright exposure blurry ae af lock"),
        GuideTopic(id: "zoom", section: "Camera", title: "Lenses, zoom & selfies", symbol: "arrow.triangle.2.circlepath", visual: .camera, destination: .camera, summary: "Zoom changes framing; Flip switches between the front and rear camera.", steps: ["Tap a zoom number or pinch the preview. Available zoom options depend on the camera.", "Use Flip for a selfie. Mirror Front Camera in Settings controls whether the saved selfie matches the mirrored preview.", "Manual rear white balance may restrict zoom to the main lens. Select Auto in White Balance to restore normal lens switching."], note: "Zooming digitally crops into the image and can reduce detail.", keywords: "front back lens 0.5 1x 2x pinch selfie"),
        GuideTopic(id: "composition", section: "Camera", title: "Grid, level, timer & flash", symbol: "grid", visual: .camera, destination: .camera, summary: "Use framing tools to line up a scene and give yourself time to get into the shot.", steps: ["Open Camera Options. Turn on Grid to line up your subject and Level to check a straight horizon.", "Choose a photo ratio to change the framing.", "Tap Timer to cycle the delay, then press the shutter. Press again during the countdown to cancel.", "Use the flash button to cycle supported flash modes."], note: "Flash and other controls appear only when the active camera supports them.", keywords: "ratio horizon delay countdown light"),
        GuideTopic(id: "white-balance", section: "Camera", title: "White balance", symbol: "thermometer.sun", visual: .warmth, destination: .camera, summary: "White balance matches the light source so neutral objects look neutral. Auto is a good starting point.", steps: ["Open Camera Options → White Balance. Try Daylight outdoors, Cloudy in overcast light, Tungsten under warm indoor bulbs, or Fluorescent under fluorescent lighting.", "On the rear camera, a preset may switch to the individual 1× main lens. Focus and exposure reset during that switch.", "Zoom is digital while this mode is active. Auto restores the combined rear camera and your previous zoom."], note: "Support depends on the camera.", keywords: "yellow blue orange temperature indoor cloudy tungsten fluorescent"),
        GuideTopic(id: "manual", section: "Camera", title: "Manual focus, ISO & shutter", symbol: "slider.horizontal.3", visual: .camera, destination: .camera, summary: "Manual controls are useful when automatic settings are not giving the result you want.", steps: ["Open Focus and enable manual focus. Move the slider toward Near or Far to choose the focus distance.", "Open Pro and enable manual exposure. ISO controls sensitivity; higher ISO can add noise.", "A slower shutter gathers more light but can blur moving subjects or a handheld shot. A faster shutter helps freeze movement.", "Return focus and exposure to Auto when the conditions change."], note: "Controls vary by hardware. Changing lenses can reset manual settings.", keywords: "grain noise motion blur professional pro"),
        GuideTopic(id: "looks", section: "Looks & Styles", title: "Find your look", symbol: "camera.filters", visual: .looks, destination: .looks, summary: "Looks are Snapper’s filters. Preview them before taking a photo or apply them later in the editor.", steps: ["Open Looks and browse collections, search, or use the Free and Favorites filters.", "Star a favorite to find it quickly. Occasion suggestions help you pick a starting point.", "In the editor, move Strength to soften or intensify a look."], note: "Premium looks can be previewed; saving with them requires Premium, but you can always save the photo without the look. Every collection has at least one free look.", keywords: "filter film search favorites collection strength"),
        GuideTopic(id: "styles", section: "Looks & Styles", title: "Save & reuse a style", symbol: "square.stack", visual: .style, destination: .styles, summary: "A style saves a look, its strength and editing adjustments for reuse.", steps: ["Open My Styles or the editor’s preset controls to save and name your style.", "Apply it to another photo or shoot with it from the camera.", "Rename or delete styles in the presets screen. You can also copy a photo’s style and paste it onto another photo in Library."], note: "Crop, finishing and selective edits do not transfer with a style. One basic personal preset is free; advanced tools and additional presets require Premium.", keywords: "preset copy paste reuse saved"),
        GuideTopic(id: "style-sharing", section: "Looks & Styles", title: "Share or import styles", symbol: "square.and.arrow.up", visual: .style, destination: .styles, summary: "A preset file carries the reusable settings. A style card is a visual way to share the style.", steps: ["Use a preset’s sharing controls to export its .snapperpreset file or style card.", "Send the file using the system share sheet, or open a received file with Snapper.", "Review the import preview before adding it to My Styles."], note: "A shared file does not unlock Premium looks or features for its recipient.", keywords: "airdrop files import export card"),
        GuideTopic(id: "adjust", section: "Editing", title: "Adjust & compare", symbol: "slider.horizontal.3", visual: .brightness, destination: .library, summary: "Edit a photo from Library. Your original stays intact and the edit remains adjustable in Snapper.", steps: ["Use Adjust for brightness, contrast, saturation, warmth, fade and grain. Scroll the tool row for Highlights, Shadows and film effects. Change one setting at a time.", "Touch and hold the photo to compare with the original, or use the comparison control.", "Use Undo and Redo to step through changes. Reset returns settings to their starting state."], note: "Keeping an edit in Snapper does not automatically export that edited version to Photos. Use Save.", keywords: "before after undo redo reset contrast saturation fade grain"),
        GuideTopic(id: "crop", section: "Editing", title: "Crop, straighten & rotate", symbol: "crop.rotate", visual: .crop, destination: .library, summary: "Cropping changes what is included in the photo. Straightening corrects a tilted horizon.", steps: ["Open Crop in the editor and choose a ratio, or use free crop.", "Adjust the crop and straighten slider to frame your subject.", "Use Rotate for 90-degree turns and Flip to mirror the photo."], note: "A crop hides parts of the original; it does not delete the source photo.", keywords: "square framing horizon mirror rotate"),
        GuideTopic(id: "finish", section: "Editing", title: "Frames, layouts & dates", symbol: "rectangle.inset.filled", visual: .save, destination: .library, summary: "Finish prepares a photo for sharing with a border, canvas layout or printed date.", steps: ["Open Finish and choose a frame and border size.", "Choose an export layout. It fits your cropped photo inside the canvas rather than applying another crop.", "Enable Date stamp and check the date before saving. If no capture date exists, choose the date to print."], note: "The date stamp is free. Frames and layouts can be previewed for free; exporting them requires Premium.", keywords: "border story post canvas stamp date"),
        GuideTopic(id: "library", section: "Library", title: "Import & organize", symbol: "photo.on.rectangle", visual: .save, destination: .library, summary: "Snapper Library keeps photos you shoot and copies of photos you choose to import.", steps: ["Tap Import Photos and select images. Only your selected images are opened.", "Browse date groups or use the filters. Tap a photo to edit it.", "Use Select for multiple photos. Delete asks for confirmation before removing items from Snapper."], note: "Deleting a photo from Snapper removes its editable copy there; do not confuse Snapper Library with the Photos app.", keywords: "album gallery photo import delete select"),
        GuideTopic(id: "batch", section: "Library", title: "Style a set of photos", symbol: "square.stack.3d.up", visual: .style, destination: .library, summary: "Give a group of photos a consistent look using Library’s selection actions.", steps: ["Tap Style a Set or Select, then choose the photos you want.", "Apply a look or saved style, paste a copied style, or finish the set.", "Review the results. Use the last-batch undo when offered to undo that operation."], note: "Batch styling and finishing can require Premium. A style transfers adjustments, not each photo’s crop.", keywords: "batch multiple selection undo paste"),
        GuideTopic(id: "saving", section: "Saving & Sharing", title: "Save, share & originals", symbol: "square.and.arrow.down", visual: .save, destination: .library, summary: "Snapper stores editable photos in its Library. Save creates a rendered copy in Photos; Share opens sharing options.", steps: ["After editing, tap Save to add the result to Photos. Allow add-only Photos access if prompted.", "Tap Share to choose where to send a rendered copy. Saved and shared copies use the format, size, quality and location settings in Export Options.", "In Settings, choose Save to Photos Automatically for new shots and Also Save Original Photo for an additional unfiltered copy."], note: "All exports are watermark-free. A photo with a Premium look or tools can always be saved for free without them: tap Save Without in the editor. Edits made while you had Premium stay exportable after it ends.", keywords: "export download where photos original jpeg heif"),
        GuideTopic(id: "settings", section: "Saving & Sharing", title: "Settings & troubleshooting", symbol: "gearshape", visual: .save, destination: nil, summary: "Use Settings to control saving, formats, photo size and camera preferences.", steps: ["Choose HEIF or JPEG and a supported photo size. Larger images use more storage; supported sizes vary with the camera.", "Enable volume-button capture where supported, and choose whether to mirror saved selfies.", "If saving or capture is blocked, check Snapper permissions in the iPhone Settings app. Restore Purchases can recover an existing purchase, and Redeem Code takes a promo code.", "Storage cleanup removes Snapper copies already saved with their current edits; review the confirmation because those copies will no longer be editable in Snapper."], note: "For an ongoing problem, use Contact Support in Settings and include the steps that triggered it.", keywords: "permissions help support purchase restore redeem promo offer code storage format megapixels volume"),
        GuideTopic(id: "collections", section: "Looks & Styles", title: "Curated collections", symbol: "square.stack", visual: .looks, destination: .looks, summary: "Start with a complete recipe combining a Snapper look with tone and film adjustments.", steps: ["Open Looks → Curated collections, or Collections in the editor’s Looks tab.", "Browse Golden Hour, After Dark, Quiet Days and Pocket Camera. Each recipe has a rendered sample and a shooting tip.", "Tap Use to try it in the camera or on the current photo. Refine it in the editor and save it as your own preset."], note: "These are recipes built from existing looks. Previewing is free; exporting them requires Premium. Future collections arrive through app updates.", keywords: "packs curated recipes golden hour after dark quiet days pocket camera digicam flash"),
        GuideTopic(id: "color-mixer", section: "Editing", title: "Control individual colors", symbol: "paintpalette", visual: .color, destination: .library, summary: "Change one color family without applying the same adjustment to the entire photo.", steps: ["Open a photo, then swipe the editor’s tool row to Color.", "Choose Red, Orange, Yellow, Green, Aqua, Blue or Purple.", "Hue shifts the color; Saturation changes its intensity; Luminance makes it lighter or darker. Nearby color bands blend together.", "Use Reset color mixer to clear all bands, or Undo to restore the previous change."], note: "Preview free; exporting color mixer edits requires Premium. Keep skin-tone changes subtle, especially in the orange and red bands.", keywords: "hsl hue saturation luminance mixer individual colors skin"),
        GuideTopic(id: "film-effects", section: "Editing", title: "Tone & film effects", symbol: "sparkles", visual: .film, destination: .library, summary: "Shape bright and dark areas, then add as much film character as the photo needs.", steps: ["Open Adjust and scroll the tool row to Highlights or Shadows. Lower Highlights to soften bright areas, or raise Shadows to lift dark detail.", "Bloom spreads soft light around bright areas. Halation adds a warm halo around bright edges.", "Vignette darkens the edges to draw attention inward. Start low, especially if your chosen look already includes film effects.", "Hold the photo to compare with the original. Effects scale with the image for previews and full-size exports."], note: "Highlights and shadows are free. Bloom, halation and vignette require Premium to export. Lowering highlights cannot recover detail already clipped in the original.", keywords: "highlights shadows bloom glow halation vignette film effects"),
        GuideTopic(id: "selective", section: "Editing", title: "Subject & background", symbol: "person.crop.rectangle", visual: .selective, destination: .library, summary: "Snapper finds foreground subjects on your iPhone so you can edit them separately from the background, and you can correct the selection with a brush.", steps: ["Open a photo and swipe the editor’s tool row to Selective. Wait for detection to finish.", "Choose Subject or Background, then adjust Brightness, Saturation and Warmth. Turn on Show Selection to see the area in red over the whole photo; pinch or double-tap the photo to zoom in on edges and hair.", "Switch to Refine Selection to fix it. Paint adds to the subject and Erase takes away; set the brush Size and Softness. One finger paints, two fingers zoom and move, and each stroke can be undone.", "If no subject is found, choose Paint the Area and paint what you want to edit. Reset selective edits to remove them; they stay with this photo and are excluded from shared presets."], note: "Detection can miss hair, transparent objects or unclear edges; zoom in and refine with a soft brush. Brush strokes follow the photo when you crop or rotate it. Export requires Premium and a usable selection; failed detection never silently removes your edits.", keywords: "mask foreground background segmentation subject selective retry brush paint erase refine zoom overlay hair edges"),
        GuideTopic(id: "curves", section: "Editing", title: "Tone curves", symbol: "chart.xyaxis.line", visual: .brightness, destination: .library, summary: "A curve reshapes the photo’s tones: how dark the shadows are, how bright the highlights, and the contrast in between.", steps: ["Open a photo and swipe the editor’s tool row to Curves. The grey shape behind the curve is the photo’s histogram.", "Tap the curve to add a point, then drag it. Lift a point in the middle to brighten mid-tones; a gentle S shape adds contrast; raise the bottom end for faded blacks.", "Choose Red, Green or Blue to curve one colour channel, for example a little blue in the shadows. Each channel’s curve applies before the RGB curve.", "Drag a point off the top or bottom of the graph, or tap Remove Point, to delete it. Reset a curve from the ••• menu."], note: "Preview free; exporting curves requires Premium. Points never overshoot, so a rising curve never dips.", keywords: "curves tone curve contrast s-curve faded matte rgb channel histogram points"),
        GuideTopic(id: "split-toning", section: "Editing", title: "Split toning", symbol: "circle.lefthalf.filled", visual: .warmth, destination: .library, summary: "Give the highlights one colour and the shadows another, like warm light with cool shadows.", steps: ["Open Color in the editor and choose Split Toning.", "Pick a hue for Highlights and raise its saturation, then do the same for Shadows. Warm highlights with blue shadows is a classic film look.", "Move Balance right to give more of the photo to the highlight colour, or left for the shadow colour."], note: "Brightness stays the same; only the colour of each tone range changes. Pure black stays neutral. Exporting split toning requires Premium.", keywords: "split toning color grading highlights shadows tint teal orange warm cool balance"),
        GuideTopic(id: "versions", section: "Editing", title: "Versions of one photo", symbol: "square.stack", visual: .style, destination: .library, summary: "Keep different edits of the same photo together, like Warm, Black & White and the Original, without undoing.", steps: ["In the editor, tap Versions at the top left of the photo.", "Save Current Edit as Version and name it. Use Duplicate This Version or New Version from Original to start another.", "Tap a version to switch to it. The version showing keeps every change, and an edit that isn’t a version yet is kept automatically when you switch.", "Touch and hold a version to rename, duplicate, save it to Photos or delete it, or Save All Versions to Photos at once."], note: "All versions share one original, so they take almost no extra space. The Library grid shows the version on screen, with a badge counting the versions.", keywords: "versions variants copies alternate edits black white warm original"),
        GuideTopic(id: "export-options", section: "Saving & Sharing", title: "Export size & quality", symbol: "gearshape", visual: .save, destination: .library, summary: "Choose the format, size and quality of saved and shared photos, and whether they keep their location.", steps: ["In the editor, tap the gear next to Save to open Export Options.", "Choose HEIF or JPEG, a size (Full, 4K, Medium or Small for social) and a quality. The file size and dimensions update for that exact photo.", "Turn off Include Location to leave the photo’s place out of saved and shared copies. Save or Share from there uses the very file that was measured."], note: "The same settings are in Settings → Saving & Sharing and apply to Library saves too. Photos saved automatically from the camera are always full size.", keywords: "export size resolution quality compression jpeg heif file size location gps metadata dimensions"),
        GuideTopic(id: "backup", section: "Library", title: "Back up & move to a new iPhone", symbol: "externaldrive.badge.plus", visual: .save, destination: nil, summary: "A backup is one file with every original in Snapper, its edits and versions, plus your presets and favorites.", steps: ["Open Settings → Backup and tap Back Up Library. Keep Snapper open until it finishes.", "Save the file to Files (for example iCloud Drive) or AirDrop it to your new iPhone.", "On the new iPhone, open the file in Snapper or use Settings → Restore from Backup. Photos already there are left as they are."], note: "Originals are copied unchanged, so a backup is about the size of your Library. Restoring twice adds nothing twice.", keywords: "backup restore new phone transfer move airdrop files icloud migrate"),
    ]

    static func search(_ query: String) -> [GuideTopic] {
        let terms = query.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        return topics.filter { topic in
            let text = ([topic.title, topic.section, topic.summary, topic.note, topic.keywords] + topic.steps).joined(separator: " ")
            return terms.allSatisfy { text.localizedStandardContains($0) }
        }
    }
}
